/**
 * Errors returned by every binding call.
 */
public 
enum FireMqError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The broker refused a request. `code` is an AMQP reply code such as 403, 404 or 406.
     */
    case Server(code: UInt16, message: String
    )
    /**
     * A mandatory publish matched no queue.
     */
    case Unroutable(message: String
    )
    /**
     * The broker rejected a publish, for example because a queue was full.
     */
    case Nacked(code: UInt16, message: String
    )
    /**
     * The connection or subscription is closed.
     */
    case Closed(message: String
    )
    /**
     * Anything else: I/O failures, invalid URLs or JSON, protocol errors.
     */
    case Other(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FireMqError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFireMqError: FfiConverterRustBuffer {
    typealias SwiftType = FireMqError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FireMqError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Server(
            code: try FfiConverterUInt16.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Unroutable(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Nacked(
            code: try FfiConverterUInt16.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Closed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FireMqError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Server(code,message):
            writeInt(&buf, Int32(1))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Unroutable(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Nacked(code,message):
            writeInt(&buf, Int32(3))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Closed(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Other(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


